// score = pgvector cosine DISTANCE (0 identical .. 2 opposite): lower is better, so HIGHER_IS_BETTER is false.
// THRESHOLD stays null on purpose: measured on 60 questions, no cut-off separates answerable from unanswerable ones
// (see raw/n8n/2026-10-01-pgvector-knowledge-base-report.md); with null, NOT_FOUND only happens when the index returns nothing.
const THRESHOLD = null;
const HIGHER_IS_BETTER = false;
const items = $input.all().map(i => i.json).filter(x => x && x.document);
const keep = items.filter(x => THRESHOLD === null || (HIGHER_IS_BETTER ? x.score >= THRESHOLD : x.score <= THRESHOLD));
const scores = items.map(x => Number(x.score).toFixed(3));
if (!keep.length) return [{ json: { verdict: 'NOT_FOUND', scores } }];
const verdict = 'FOUND\n' + keep.map(x => `[${x.document.metadata.topic}] ${x.document.pageContent.replace(/^.*\n/, '')}`).join('\n\n');
return [{ json: { verdict, scores } }];
